    fn default() -> Self {
        Self::new()
    }
}

impl ResourceRegistry {
    pub fn new() -> Self { … }

    /// Advertise every sealed plugin as `blob://<plugin_id>`.
    pub fn with_blob_catalog() -> Self { … }

    pub fn add_resource(&mut self, resource: ResourceInfo) {
        self.resources.push(resource);
