                if let Err(e) = sender.send(Message::Pong(data)).await {
                    error!(error = %e, "Failed to send pong");
                    break;
                }
            }
            Ok(Message::Close(_)) => {
                info!("WebSocket client disconnected");
                break;
            }
            Ok(_) => {} // Ignore binary, pong, etc.
            Err(e) => {
                error!(error = %e, "WebSocket error");
                break;
            }
        }
    }

