    #[serde(skip_serializing_if = "Option::is_none")]
    pub api_key=***    /// API key environment variable name (default: API_KEY)
    #[serde(default = "default_api_key_env")]
    pub api_key_env: String,

    /// Authentication method
    #[serde(default)]
    pub auth_method: AuthMethod,

    /// Custom headers for HTTP-based MCP servers
    #[serde(default)]
    pub headers: HashMap<String, String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum ExternalMcpTransport {
    #[default]
    Stdio,
    StreamableHttp,
}

fn default_api_key_env() -> String {
    "API_KEY".to_string()
}

/// Authentication method for MCP servers
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum AuthMethod {
    /// No authentication
    #[default]
    None,

    /// API key in environment variable
    EnvVar,

    /// Bearer token in Authorization header (for HTTP-based MCP)
    BearerToken,

    /// Custom header (specify in headers field)
    CustomHeader,
}

